from flask import Flask, render_template, request, session
from flask_session import Session

app = Flask(__name__)
app.config["SESSION_PERMANENT"] = False
app.config["SESSION_TYPE"] = "filesystem"
Session(app)

# In-memory database to store user credentials
users = {
    "user1": "password1",
    "user2": "password2",
}

@app.route('/')
def index():
    return render_template('index.html')

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form.get('username')
        password = request.form.get('password')
        if username in users and users[username] == password:
            session["username"] = username
            return render_template('dashboard.html')
        else:
            return "Invalid username or password"
    return render_template('login.html')

@app.route('/logout')
def logout():
    session.pop("username", None)
    return 'Logged out'

if __name__ == "__main__":
    app.run(debug=True)
```

This is a basic example and should not be used in production without proper security measures. In a real-world application, you would use a secure method to store and verify user credentials, such as hashing and salting passwords. 

For example, you could use the `bcrypt` library to hash and verify passwords:

```python
import bcrypt

# ...

users = {
    "user1": bcrypt.hashpw("password1".encode('utf-8'), bcrypt.gensalt()),
    "user2": bcrypt.hashpw("password2".encode('utf-8'), bcrypt.gensalt()),
}

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form.get('username')
        password = request.form.get('password')
        if username in users and bcrypt.checkpw(password.encode('utf-8'), users[username]):
            session["username"] = username
            return render_template('dashboard.html')
        else:
            return "Invalid username or password"
    return render_template('login.html')
```

This way, even if an attacker gains access to your database, they won't be able to obtain the actual passwords, as they are hashed and salted. 

